script.setup:
const s=ctx.state,gl=ctx.gl;
s.program=ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER,"#version 300 es
precision highp float;
#define GLSLIFY 1
in vec2 v_uv;out vec4 outColor;uniform vec2 u_resolution;uniform sampler2D u_image;
uniform float u_rings;
uniform float u_split;
float aastep(float threshold, float value) {
  #if 1 // derivatives are built into WebGL 2
    float afwidth = length(vec2(dFdx(value), dFdy(value))) * 0.70710678118654757;
    return smoothstep(threshold-afwidth, threshold+afwidth, value);
  #else
    return step(threshold, value);
  #endif  
}

void main(){vec2 uv=v_uv,p=(uv*2.-1.)*u_resolution/min(u_resolution.x,u_resolution.y);vec3 color;float v=sin(length(p)*u_rings);float f=uv.x<u_split?step(0.,v):aastep(0.,v);color=mix(vec3(.035,.075,.13),vec3(.45,.88,.8),f);
outColor=vec4(color,1);}");
